CREATE TABLE IF NOT EXISTS cms_theme_settings(id INTEGER PRIMARY KEY CHECK(id=1),theme_key VARCHAR(120) NOT NULL DEFAULT 'vazin-default',style_tokens_json TEXT NOT NULL DEFAULT '{}',template_parts_json TEXT NOT NULL DEFAULT '{}',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO cms_theme_settings(id,theme_key) VALUES(1,'vazin-default') ON CONFLICT(id) DO NOTHING;
CREATE TABLE IF NOT EXISTS cms_template_assignments(id BIGSERIAL PRIMARY KEY,scope_type VARCHAR(32) NOT NULL CHECK(scope_type IN('global','content_type','taxonomy','page')),scope_key VARCHAR(190) NOT NULL,template_key VARCHAR(190) NOT NULL,priority INTEGER NOT NULL DEFAULT 100,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(scope_type,scope_key));
CREATE TABLE IF NOT EXISTS cms_site_templates(id BIGSERIAL PRIMARY KEY,template_key VARCHAR(190) NOT NULL UNIQUE,label VARCHAR(255) NOT NULL,template_type VARCHAR(32) NOT NULL CHECK(template_type IN('front-page','home','single','page','archive','taxonomy','search','404','part')),block_document TEXT NOT NULL DEFAULT '',block_schema_version INTEGER NOT NULL DEFAULT 1,is_system BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
